/**
 * Tag (spec/02 §3.2): an outlined word („Android“, „Verfügbar“, „Beta“) in caption at weight 400 in text, 1 dp
 * borderStrong frame, radius small, 1 dp above and below, 8 dp at the sides. Never a status colour, not interactive.
 */
@Composable
fun SbTag(text: String, modifier: Modifier = Modifier) {
    val t = SebaroTheme.tokens
    Text(
        text,
        style = SebaroTheme.typography.caption,
        color = SebaroTheme.colors.text,
        maxLines = 1,
        modifier = modifier
            .border(t.borderWidth.control, SebaroTheme.colors.borderStrong, t.shapes.small)
            .padding(horizontal = t.space.s2, vertical = 1.dp),   // the web's padding: 1px 8px
    )
}

/** Tags in a row that wraps, 8 dp both ways (sb-tags): SbTag and SbDemoMarker. */
@Composable
fun SbTags(modifier: Modifier = Modifier, content: @Composable () -> Unit) {
    val t = SebaroTheme.tokens
    SbFlowRow(
        modifier,
        horizontalArrangement = Arrangement.spacedBy(t.space.s2),
        verticalArrangement = Arrangement.spacedBy(t.space.s2),
    ) { content() }
}
